public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Request body is null or blank');
        }

        Object rootObj;
        try {
            rootObj = JSON.deserializeUntyped(body);
        } catch (JSONException e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(rootObj instanceof Map<String, Object>)) {
            throw new PayloadException('JSON root is not an object');
        }
        Map<String, Object> root = (Map<String, Object>) rootObj;

        // orderNumber (from "number")
        Object numberObj = root.get('number');
        if (numberObj == null) {
            throw new PayloadException('Missing "number"');
        }
        String orderNumber = String.valueOf(numberObj);
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('"number" is blank');
        }

        // orderDate (from "date", ISO yyyy-MM-dd)
        Date orderDate = null;
        Object dateObj = root.get('date');
        if (dateObj != null) {
            try {
                orderDate = Date.valueOf(String.valueOf(dateObj));
            } catch (Exception e) {
                throw new PayloadException('Invalid "date" format (expected yyyy-MM-dd): ' + e.getMessage());
            }
        }

        // currencyCode (from "currency")
        String currencyCode = null;
        Object currencyObj = root.get('currency');
        if (currencyObj != null) {
            currencyCode = String.valueOf(currencyObj);
        }

        // customerEmail (from "customer.email")
        String customerEmail = null;
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Map<String, Object> customerMap = (Map<String, Object>) customerObj;
            Object emailObj = customerMap.get('email');
            if (emailObj != null) {
                customerEmail = String.valueOf(emailObj);
            }
        }

        // lines
        List<Line> lines = new List<Line>();
        Decimal total = 0;

        Object linesObj = root.get('lines');
        if (linesObj instanceof List<Object>) {
            List<Object> linesList = (List<Object>) linesObj;
            for (Object lineObj : linesList) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    continue; // ignore non-object items
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                // sku (required)
                Object skuObj = lineMap.get('sku');
                if (skuObj == null) {
                    throw new PayloadException('Line missing "sku"');
                }
                String sku = String.valueOf(skuObj);

                // quantity (required, positive integer)
                Object qtyObj = lineMap.get('quantity');
                if (qtyObj == null) {
                    throw new PayloadException('Line missing "quantity"');
                }
                Integer quantity;
                try {
                    quantity = Integer.valueOf(String.valueOf(qtyObj));
                } catch (Exception e) {
                    throw new PayloadException('Invalid "quantity"');
                }
                if (quantity <= 0) {
                    throw new PayloadException('"quantity" must be positive');
                }

                // unitPrice (required, non-negative)
                Object priceObj = lineMap.get('unitPrice');
                if (priceObj == null) {
                    throw new PayloadException('Line missing "unitPrice"');
                }
                Decimal unitPrice;
                try {
                    unitPrice = Decimal.valueOf(String.valueOf(priceObj));
                } catch (Exception e) {
                    throw new PayloadException('Invalid "unitPrice"');
                }
                if (unitPrice < 0) {
                    throw new PayloadException('"unitPrice" cannot be negative');
                }

                // discount (optional, 0..1, default 0)
                Decimal discount = 0;
                Object discountObj = lineMap.get('discount');
                if (discountObj != null) {
                    try {
                        discount = Decimal.valueOf(String.valueOf(discountObj));
                    } catch (Exception e) {
                        throw new PayloadException('Invalid "discount"');
                    }
                    if (discount < 0) discount = 0;
                    if (discount > 1) discount = 1;
                }

                // lineTotal = quantity * unitPrice * (1 - discount), rounded half-up to 2 dp
                Decimal lineTotal = quantity * unitPrice * (1 - discount);
                lineTotal = lineTotal.setScale(2, RoundingMode.HALF_UP);

                Line line = new Line();
                line.sku = sku;
                line.quantity = quantity;
                line.unitPrice = unitPrice;
                line.discount = discount;
                line.lineTotal = lineTotal;

                lines.add(line);
                total += lineTotal;
            }
        }

        // total rounded to 2 dp half-up
        total = total.setScale(2, RoundingMode.HALF_UP);

        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total;

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines != null ? order.lines.size() : 0);
        ack.put('total', order.total != null ? order.total : 0);
        return JSON.serialize(ack);
    }
}
