@IsTest
public class RenewalServiceTest {

    @TestSetup
    static void setup() {
        Application.Selector.setMock(null);
        Application.UnitOfWork.setMock(null);
    }

    private static void resetMocks() {
        Application.Selector.setMock(null);
        Application.UnitOfWork.setMock(null);
    }

    // ------------------------------------------------------------
    // Helper: build a fake Opportunity with only the fields used
    // ------------------------------------------------------------
    private static Opportunity buildOpp(
        Id id,
        String name,
        Id accountId,
        Id ownerId,
        String stageName,
        Date closeDate,
        Decimal amount
    ) {
        Opportunity o = new Opportunity();
        o.Id = id;
        o.Name = name;
        o.AccountId = accountId;
        o.OwnerId = ownerId;
        o.StageName = stageName;
        o.CloseDate = closeDate;
        o.Amount = amount;
        return o;
    }

    // ------------------------------------------------------------
    // 1. Null / empty input → nothing happens
    // ------------------------------------------------------------
    @IsTest
    static void createRenewals_nullOrEmpty_doesNothing() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);

        Application.UnitOfWork.setMock(uowMock);
        Application.Selector.setMock(selectorMock);

        RenewalService.createRenewals(null);
        RenewalService.createRenewals(new Set<Id>());

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).registerNew((SObject) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).commitWork();

        resetMocks();
    }

