        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        // Dynamically include fields from the Credit_Review field set so admins
        // can add/remove fields without code changes.
        Schema.FieldSet creditReviewFieldSet = Schema.SObjectType.Account.FieldSets.Credit_Review;
        Map<String, Schema.SObjectField> fieldMap = Account.SObjectType.getDescribe().fields.getMap();

        for (Schema.FieldSetMember fsm : creditReviewFieldSet.getFields()) {
            Schema.SObjectField field = fieldMap.get(fsm.getFieldPath());
            if (field != null) {
                fields.add(field);
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
