    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        ContactsSelector contactsSelector = new ContactsSelector();

        // Build the main query with contact subquery using the alternative subSelectQuery signature
        fflib_QueryFactory queryFactory = newQueryFactory()
            .selectFields(getSObjectFieldList())
            .setCondition('Id IN :accountIds')
            .subSelectQuery('Contacts', contactsSelector.getSObjectFieldList(), 'AccountId IN :accountIds');

        return (List<Account>) Database.query(queryFactory.toSOQL());
