trigger AccountTrigger on Account (after insert) {
    if (Trigger.isAfter && Trigger.isInsert) {
        List<Id> newAccountIds = new List<Id>();
        for (Account a : Trigger.new) {
            newAccountIds.add(a.Id);
        }
        // Split into chunks of 100 to stay within the 100 callouts per transaction limit.
        // Each chunk gets its own Queueable job; max 2 jobs for 200 accounts.
        Integer chunkSize = 100;
        for (Integer i = 0; i < newAccountIds.size(); i += chunkSize) {
            List<Id> chunk = new List<Id>();
            Integer end = Math.min(i + chunkSize, newAccountIds.size());
            for (Integer j = i; j < end; j++) {
                chunk.add(newAccountIds[j]);
            }
            System.enqueueJob(new ErpCustomerSync(chunk));
        }
    }
}
