public with sharing class LineItemDiscountHandler {

    /**
     * Applies standard product discounts to new opportunity line items that don't
     * already have a discount value. Bulk-safe for up to 200 lines per transaction.
     * Uses a single SOQL query to fetch all product families, then delegates discount
     * logic to PricingRules.standardDiscountForFamily to keep rules centralized.
     *
     * @param newLines list of OpportunityLineItem records being inserted
     */
    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        // Collect unique Product2Ids for lines needing a discount
        Set<Id> productIdsNeedingDiscount = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDiscount.add(line.Product2Id);
            }
        }

        if (productIdsNeedingDiscount.isEmpty()) {
            return;
        }

        // Single query to fetch all product families - avoids N-query problem in
        // PricingRules.standardDiscountFor which queries Product2 per call.
        // We still keep discount logic in PricingRules via standardDiscountForFamily.
        Map<Id, String> productFamilyById = new Map<Id, String>();
        for (Product2 p : [SELECT Id, Family FROM Product2 WHERE Id IN :productIdsNeedingDiscount]) {
            productFamilyById.put(p.Id, p.Family);
        }

        // Apply standard discount per product family
        // PricingRules.standardDiscountForFamily handles null family (returns 0)
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                String family = productFamilyById.get(line.Product2Id);
                line.Discount = PricingRules.standardDiscountForFamily(family);
            }
        }
    }
}
