import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _value = '';
    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this._syncActiveOption();
    }

    @track activeOptionId = '';
    @track optionIds = [];

    connectedCallback() {
        this._syncActiveOption();
    }

    _generateOptionId(value) {
        return `status-option-${value}`;
    }

    _syncActiveOption() {
        this.optionIds = this.options.map(opt => this._generateOptionId(opt.value));

        if (this._value && this.options.some(opt => opt.value === this._value)) {
            this.activeOptionId = this._generateOptionId(this._value);
        } else if (this.options.length > 0) {
            this.activeOptionId = this._generateOptionId(this.options[0].value);
        } else {
            this.activeOptionId = '';
        }
    }

    _moveActive(direction) {
        if (!this.activeOptionId || this.options.length === 0) return;

        const currentIndex = this.optionIds.indexOf(this.activeOptionId);
        if (currentIndex === -1) return;

        let newIndex;
        if (direction === 'down') {
            newIndex = Math.min(currentIndex + 1, this.options.length - 1);
        } else if (direction === 'up') {
            newIndex = Math.max(currentIndex - 1, 0);
        } else if (direction === 'home') {
            newIndex = 0;
        } else if (direction === 'end') {
            newIndex = this.options.length - 1;
        } else {
            return;
        }

        this.activeOptionId = this.optionIds[newIndex];
    }

    _selectActive() {
        if (!this.activeOptionId) return;

        const activeOption = this.options.find(opt => this._generateOptionId(opt.value) === this.activeOptionId);
        if (!activeOption) return;

        if (this._value !== activeOption.value) {
            this._value = activeOption.value;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: activeOption.value },
                bubbles: true,
                composed: true
            }));
        }
    }

    handleKeydown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        switch (key) {
            case 'ArrowDown':
                this._moveActive('down');
                break;
            case 'ArrowUp':
                this._moveActive('up');
                break;
            case 'Home':
                this._moveActive('home');
                break;
            case 'End':
                this._moveActive('end');
                break;
            case 'Enter':
            case ' ':
                this._selectActive();
                break;
        }
    }

    handleOptionClick(event) {
        const optionElement = event.currentTarget;
        const value = optionElement.dataset.value;

        if (this._value !== value) {
            this._value = value;
            this.activeOptionId = this._generateOptionId(value);
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            }));
        } else {
            this.activeOptionId = this._generateOptionId(value);
        }
    }

    get computedOptions() {
        return this.options.map(opt => ({
            ...opt,
            id: this._generateOptionId(opt.value),
            selected: opt.value === this._value,
            active: this._generateOptionId(opt.value) === this.activeOptionId,
            optionClass: this._generateOptionId(opt.value) === this.activeOptionId ? 'active' : ''
        }));
    }
}
