public class HouseholdService {

    /**
     * Exception thrown when an illegal argument is provided.
     */
    public class IllegalArgumentException extends Exception {}

    /**
     * Exception thrown when an illegal state is encountered.
     */
    public class IllegalStateException extends Exception {}

    /**
     * Creates a single NPSP Household Account and associates all given contacts to it.
     * The first contact becomes the household's primary contact (npe01__One2OneContact__c).
     * NPSP automatically names the household and generates greetings.
     *
     * @param members  List of new Contact records (no Id, no AccountId). Must not be null or empty.
     * @return         Id of the created Household Account.
     * @throws IllegalArgumentException if members is null or empty.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty');
        }

        // Resolve the Household Account record type by DeveloperName (no hard-coded Ids)
        Map<String, Schema.RecordTypeInfo> rtInfos = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName();
        Schema.RecordTypeInfo hhRtInfo = rtInfos.get('HH_Account');
        if (hhRtInfo == null) {
            throw new IllegalStateException('Household Account record type (DeveloperName HH_Account) not found');
        }
        Id householdRecordTypeId = hhRtInfo.getRecordTypeId();

        // Create the household account. A temporary name is required for insert;
        // NPSP automation will rename it once the primary contact is assigned.
        Account household = new Account(
            RecordTypeId = householdRecordTypeId,
            Name = 'Household'  // Temporary placeholder; NPSP will overwrite via npe01__One2OneContact__c trigger
        );
        insert household;

        // Clone contacts to avoid mutating the caller's list, then stamp the new AccountId
        List<Contact> contactsToInsert = new List<Contact>();
        for (Contact m : members) {
            Contact c = m.clone(false, true, false, false);
            c.AccountId = household.Id;
            contactsToInsert.add(c);
        }
        insert contactsToInsert;

        // Assign the first contact as the household's primary contact.
        // This triggers NPSP household naming and greeting generation.
        household.npe01__One2OneContact__c = contactsToInsert[0].Id;
        update household;

        return household.Id;
    }
}
