public inherited sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query 1: Opportunities with primary contact and amount
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // Validate entire batch before any DML
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact is the primary contact on the opportunity');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Amount exceeds opportunity amount');
            }
        }

        // Query 2: Existing OpportunityContactRoles for the pairs
        Map<String, OpportunityContactRole> existingOcrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
            AND ContactId IN :contactIds
        ]) {
            existingOcrMap.put(ocr.OpportunityId + ':' + ocr.ContactId, ocr);
        }

        // Query 3: Existing Partial Soft Credits for the pairs
        Map<String, npsp__Partial_Soft_Credit__c> existingPscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
            AND npsp__Contact__c IN :contactIds
        ]) {
            existingPscMap.put(psc.npsp__Opportunity__c + ':' + psc.npsp__Contact__c, psc);
        }

        // Classify OCRs: keep, delete (role mismatch), or create new
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        Map<String, Id> contactRoleIdMap = new Map<String, Id>(); // key -> OCR Id (after all DML)

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            OpportunityContactRole existingOcr = existingOcrMap.get(key);

            if (existingOcr != null) {
                if (existingOcr.Role == req.role) {
                    // Keep existing OCR
                    contactRoleIdMap.put(key, existingOcr.Id);
                } else {
                    // Role mismatch: delete old, will insert new
                    ocrsToDelete.add(existingOcr);
                    OpportunityContactRole newOcr = new OpportunityContactRole(
                        OpportunityId = req.opportunityId,
                        ContactId = req.contactId,
                        Role = req.role,
                        IsPrimary = false
                    );
                    ocrsToInsert.add(newOcr);
                }
            } else {
                // No existing OCR: create new
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role,
                    IsPrimary = false
                );
                ocrsToInsert.add(newOcr);
            }
        }

        // DML 1: Delete OCRs with wrong role
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // DML 2: Insert all new OCRs (both brand-new and replacements)
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
            for (OpportunityContactRole ocr : ocrsToInsert) {
                contactRoleIdMap.put(ocr.OpportunityId + ':' + ocr.ContactId, ocr.Id);
            }
        }

        // Prepare Partial Soft Credit changes
        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            Id contactRoleId = contactRoleIdMap.get(key);

            if (contactRoleId == null) {
                throw new SoftCreditException('Contact role not found after creation');
            }

            npsp__Partial_Soft_Credit__c existingPsc = existingPscMap.get(key);

            if (existingPsc != null) {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role_Name__c = req.role;
                existingPsc.npsp__Contact_Role_ID__c = contactRoleId;
                pscsToUpdate.add(existingPsc);
            } else {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = contactRoleId
                );
                pscsToInsert.add(newPsc);
            }
        }

        // DML 3: Insert new partial soft credits
        if (!pscsToInsert.isEmpty()) {
            insert pscsToInsert;
        }

        // DML 4: Update existing partial soft credits
        if (!pscsToUpdate.isEmpty()) {
            update pscsToUpdate;
        }
    }
}
